def max_drawdown(values):
    # Largest fall from an earlier high to a later value
    ref = values[0]
    worst = 0
    for v in values[1:]:
        if v < ref:
            worst = max(worst, ref - v)
        ref = max(ref, v)
    return worst

def max_drawdown(values):
    ref = values[0]
    worst = 0
    for v in values[1:]:
        if v > ref:
            ref = v
        worst = max(worst, ref - v)
    return worst

def max_drawdown(values):
    # Largest fall from an earlier high to a later value
    ref = values[0]
    worst = 0
    for v in values[1:]:
        if v < ref:
            worst = max(worst, ref - v)
        ref = max(ref, v)
    return worst
